import os, sys, json, math, random, datetime

def main():
    data = json.loads(open('config.json').read())
    now = datetime.datetime.now()
    path = os.path.join(sys.path[0], 'output')
    value = math.sqrt(random.uniform(0, 100))
    return {'data': data, 'time': now, 'path': path, 'value': value}

if __name__ == '__main__':
    print(main())

